const ticketItem = $('Postgres: Select Ticket').first()?.json;
if (!ticketItem || ticketItem.id == null) throw new Error('Ticket not found.');
const ticket = ticketItem;

// Select Ticket Comments / Select Related Deal legitimately return zero
// rows a lot (no comments yet, no linked deal) — those nodes have
// "Always Output Data" on so the chain doesn't just stop dead (n8n's
// default behavior when a node's query matches nothing), but that means
// their one placeholder item has no real columns on it. Filter/guard on
// an actual id instead of assuming the row is real.
const comments = $('Postgres: Select Ticket Comments').all()
  .filter((i) => i.json.id != null)
  .map((i) => ({ kind: 'comment', ...i.json }));
const events = $('Postgres: Select Ticket Activity Log').all()
  .filter((i) => i.json.id != null)
  .map((i) => ({ kind: 'event', ...i.json }));
const timeline = [...comments, ...events].sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

const counts = $('Postgres: Select Ticket Counts').first()?.json || { open_count: 0, previous_count: 0 };
const relatedDealRow = $('Postgres: Select Related Deal').first()?.json;
const relatedDeal = relatedDealRow && relatedDealRow.id != null ? relatedDealRow : null;

return [{
  json: {
    ...ticket,
    timeline,
    open_ticket_count: Number(counts.open_count) || 0,
    previous_ticket_count: Number(counts.previous_count) || 0,
    related_deal: relatedDeal,
  },
}];

