const body = $('Webhook: archive-ticket').first().json.body || {};
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" is required.');
return [{ json: { id } }];

const body = $input.first().json.body || {};

// Honeypot — a real browser never fills this (it's visually hidden via
// CSS on the public form); a bot filling every field will. Silently
// pretend success without touching the database.
if ((body.website || '').toString().trim()) {
  return [{ json: { spam: true } }];
}

const name = (body.name || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const subject = (body.subject || '').toString().trim();
const description = (body.description || '').toString().trim();
if (!name) throw new Error('"name" is required.');
if (!email || !email.includes('@')) throw new Error('A valid "email" is required.');
if (!subject) throw new Error('"subject" is required.');

const VALID_PRIORITIES = ['low', 'normal', 'high', 'urgent'];
const priority = VALID_PRIORITIES.includes(body.priority) ? body.priority : 'normal';
const SLA_HOURS = { urgent: 4, high: 8, normal: 24, low: 72 };

return [{
  json: {
    spam: false,
    name,
    email,
    subject,
    description,
    priority,
    slaHours: SLA_HOURS[priority],
  },
}];

