const payload = $('Check Payload: update-ticket').first().json;
const current = $input.first().json;
const changes = [];

if (payload.status !== null && payload.status !== current.status) {
  changes.push(`status changed from "${current.status}" to "${payload.status}"`);
}
if (payload.priority !== null && payload.priority !== current.priority) {
  changes.push(`priority changed from "${current.priority}" to "${payload.priority}"`);
}
if (payload.assignedUser !== null && payload.assignedUser !== current.assigned_user) {
  changes.push(`reassigned`);
}

const summary = changes.length > 0
  ? `${payload.requesterName} ${changes.join(', ')}`
  : '';

return [{ json: { ...payload, hasChanges: changes.length > 0, changeSummary: summary } }];

